@RestController
@RequestMapping("/api/v1")
public class ApiController {

    final PersonService personService;
    final ProductService productService;

    public ApiController(PersonService personService, ProductService productService) {
        this.personService = personService;
        this.productService = productService;
    }

    @GetMapping("/person")
    public List<Person> getAllPersons() {
        return personService.getAllPersons();
    }

    @GetMapping("/person/{id}")
    public Person getPerson(@PathVariable Long id) {
        return personService.findById(id);
    }

    @GetMapping("/products")
    public List<Product> getAllProducts() {
        return productService.getAllProducts();
    }

    @GetMapping("/products/coffee")
    public List<Product> getAllCoffee() {
        return productService.getAllProducts()
                .stream()
                .filter(product -> product.getProductType() == ProductType.COFFEE)
                .toList();
    }

    @GetMapping("/products/beer")
    public List<Product> getAllBeers() {
        return productService.getAllProducts()
                .stream()
                .filter(product -> product.getProductType() == ProductType.BEER)
                .toList();
    }

}

@Component
public class AuthenticationFailureListener implements ApplicationListener<AuthenticationFailureBadCredentialsEvent> {

    private static final Logger logger = LogManager.getLogger(AuthenticationFailureListener.class);

    private final HttpServletRequest request;

    public AuthenticationFailureListener(HttpServletRequest request) {
        this.request = request;
    }

    @Override
    public void onApplicationEvent(AuthenticationFailureBadCredentialsEvent e) {
        logger.error("Failed login for username: {}", e.getAuthentication().getName());
    }
}

@Configuration
public class ResourceConfig implements WebMvcConfigurer {

    @Override
    public void addResourceHandlers(final ResourceHandlerRegistry registry) {
        registry.addResourceHandler("/uploads/**", "/image/**")
                .addResourceLocations("file:uploads/", "file:image/");

    }
}

@Configuration
@EnableWebSecurity
public class SecurityConfig {

    @Bean
    public PasswordEncoder passwordEncoder() {
        return new Pbkdf2PasswordEncoder();
    }

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http
                .authorizeRequests()
                .antMatchers("/").permitAll()
                .antMatchers("/api/**").permitAll()
                .antMatchers("/h2-console/**").permitAll()
                .antMatchers("/", "/webjars/**", "/css/**", "/home", "/index", "/register", "/products/direct/**","/image/**").permitAll()
                .antMatchers("/orders/add", "/orders/myorders/**", "/uploadimage").hasAnyRole("ADMIN", "CUSTOMER")
                .antMatchers("/products/**", "/orders/**", "/persons/**").hasRole("ADMIN")
                .anyRequest().authenticated()
                .and()
                .formLogin(
                        form -> form.loginPage("/login")
                                .loginProcessingUrl("/login")
                                .failureUrl("/login?error")
                                .defaultSuccessUrl("/")
                                .permitAll()
                ).logout(
                        logout -> logout.logoutRequestMatcher(new AntPathRequestMatcher("/logout"))
                                .permitAll()
                )
                .csrf().disable().headers().frameOptions().disable()
                .and().requestCache().disable();

        return http.build();
    }

}

