@Controller
@RequestMapping("/orders")
public class OrderController {
    private final ProductService productService;
    private final OrderService orderService;
    private final PersonService personService;

    public OrderController(ProductService productService, OrderService orderService, PersonService personService) {
        this.productService = productService;
        this.orderService = orderService;
        this.personService = personService;
    }


    @ModelAttribute("products")
    public List<Product> populateProducts() {
        return productService.getAllProducts();
    }

    @GetMapping("/myorders")
    public String showMyOrders(Model model, Principal principal) {
        var user = principal.getName();
        var person = personService.findByUsername(user);
        model.addAttribute("orders", orderService.findByPerson(person));
        return "order/mylist";
    }

    @GetMapping(value = "/myorders/export.yaml", produces = MediaType.APPLICATION_OCTET_STREAM_VALUE)
    @ResponseBody
    public byte[] exportYaml(Principal principal) {
        var user = principal.getName();
        var person = personService.findByUsername(user);
        var orders = orderService.findByPerson(person);
        var yamlOutput = YamlImportExport.exportOrders(orders);
        return yamlOutput.getBytes(StandardCharsets.UTF_8);
    }

    @GetMapping(value = "/myorders/export.xml", produces = MediaType.APPLICATION_OCTET_STREAM_VALUE)
    @ResponseBody
    public byte[] exportXml(Principal principal) throws XMLStreamException, TransformerException {
        var user = principal.getName();
        var person = personService.findByUsername(user);
        var orders = orderService.findByPerson(person);
        var xmlOutput = XMLExporter.exportOrders(orders);
        return xmlOutput.getBytes(StandardCharsets.UTF_8);
    }

    @GetMapping("/myorders/import")
    public String index(Model model) {
        return "order/import";
    }

    @PostMapping( "/myorders/import")
    public String singleFileUpload(@RequestParam("file") MultipartFile file, RedirectAttributes redirectAttributes, Principal principal) {
        var user = principal.getName();
        var person = personService.findByUsername(user);

        if (file.isEmpty()) {
            return "redirect:/orders/myorders/import";
        }

        try {
            if (file.getContentType().contains("yaml") || fileExtIs(file, ".yaml") || fileExtIs(file, ".yml")) {
                YamlImportExport.importOrders(file.getInputStream(), person)
                        .forEach(orderService::save);
            } else if (file.getContentType().equals("text/xml") || fileExtIs(file, ".xml")) {
                var parser = new XML2OrderParser();
                parser.parse(file.getInputStream())
                        .stream()
                        .map(eo -> ExportOrderConvertor.createOrders(eo,person))
                        .forEach(orderService::save);;
            }


        } catch (Exception e) {
            throw new RuntimeException(e);
        }

        return "redirect:/orders/myorders";
    }

    private boolean fileExtIs(MultipartFile file, String ext) {
        return file.getOriginalFilename().endsWith(ext);
    }


    @GetMapping("/add")
    public String showOrderForm(Model model) {
        Order order = new Order();
        order.setOrderDate(new Date());
        order.addOrderLine(new OrderLine());
        model.addAttribute("order", order);
        return "order/add";
    }

    @PostMapping(value = "/add", params = "addOrderLine")
    public String addOrderLine(Order order, BindingResult result) {
        OrderLine orderLine = new OrderLine();
        order.addOrderLine(orderLine);
        return "order/add";
    }

    @PostMapping(value = "/add", params = "removeOrderLine")
    public String removeOrderLine(Order order, BindingResult result, HttpServletRequest request) {
        int orderLineId = Integer.parseInt(request.getParameter("removeOrderLine"));
        order.getOrderLines().remove(orderLineId);

        return "order/add";
    }

    @PostMapping("/add")
    public String saveOrder(@Valid Order order, BindingResult result, Principal principal, RedirectAttributes redirectAttributes) {
        if (!result.hasErrors()) {
            try {
                List<OrderLine> orderLines = order.getOrderLines();
                int lastOrderLineIndex = orderLines.size() - 1;

                if (orderLines.get(lastOrderLineIndex).getProduct() == null) {
                    orderLines.remove(lastOrderLineIndex);
                }

                if (orderLines.isEmpty()) {
                    order.addOrderLine(new OrderLine());
                    throw new Exception("At least one product must be added to the Order");
                }

                for (OrderLine orderLine : orderLines) {
                    var prod = orderLine.getProduct();
                    orderLine.setProductName(prod.getProductName());
                    orderLine.setPrice(prod.getPrice());

                    if (orderLine.getQuantity() == 0) {
                        throw new Exception("Quantity of product " + orderLine.getProductName() + " must be positive");
                    }
                }

                order.setPerson(personService.findByUsername(principal.getName()));
                order.getOrderLines().forEach(orderLine -> orderLine.setOrder(order));

                orderService.save(order);

                redirectAttributes.addFlashAttribute("message", "Your order has been placed successfully.");

                return "redirect:/orders/add";
            } catch (Exception e) {
                result.reject(null, e.getMessage());
            }
        }

        return "order/add";
    }

    @GetMapping
    public String listOrders(Model model) {
        model.addAttribute("orders", orderService.findAll());
        return "order/list";
    }
}

@Controller
@RequestMapping("/persons")
public class PersonController {
    private final PersonService personService;

    public PersonController(PersonService personService) {
        this.personService = personService;
    }

    @GetMapping
    public String listPersons(Model model) {
        model.addAttribute("persons", personService.getAllPersons());
        return "person/list";
    }

    @GetMapping("/edit/{id}")
    public String showPersonEdit(@PathVariable Long id, Model model) {
        Person person = personService.findById(id);
        model.addAttribute("person", person);
        return "person/edit";
    }

    @GetMapping("/add")
    public String showPersonAdd(Model model) {
        model.addAttribute("person", new Person());
        return "person/edit";
    }

    @PostMapping({"/edit/{id}", "/add"})
    public String savePerson(@Valid Person person, BindingResult result, Model model, RedirectAttributes redirectAttributes) {
        if (result.hasErrors()) {
            return "person/edit";
        }

        boolean isAdd = person.getId() == null;

        if (isAdd) {
            person.setPassword("123456");
        }

        personService.savePerson(person);

        if (isAdd) {
            redirectAttributes.addFlashAttribute("message", "Person has been created successfully.");
        } else {
            redirectAttributes.addFlashAttribute("message", "Person has been updated successfully.");
        }

        return "redirect:/persons/edit/" + person.getId();
    }

    @GetMapping("/delete/{id}")
    public String deletePerson(@PathVariable Long id) {
        personService.removePerson(id);
        return "redirect:/persons";
    }

}

@Controller
@RequestMapping("/products")
public class ProductController {
    private ProductService productService;

    public ProductController(ProductService productService) {
        this.productService = productService;
    }

    @GetMapping("/add")
    public String showProductAdd(Model model) {
        model.addAttribute("product", new Product());
        return "product/edit";
    }

    @PostMapping({"/edit/{id}", "/add"})
    public String saveProduct(@Valid Product product, BindingResult result, Model model, RedirectAttributes redirectAttributes) {
        boolean isAdd = product.getId() == null;

        if (result.hasErrors()) {
            return "product/edit";
        }

        productService.save(product);

        if (isAdd) {
            redirectAttributes.addFlashAttribute("message", "Your product has been created successfully.");
        } else {
            redirectAttributes.addFlashAttribute("message", "Your product has been updated successfully.");
        }

        return "redirect:/products/edit/" + product.getId();
    }

    @GetMapping("/edit/{id}")
    public String showProductEdit(@PathVariable Long id, Model model) {
        model.addAttribute("product", productService.getProduct(id));
        return "product/edit";
    }

    @GetMapping("/delete/{id}")
    public String deleteProduct(@PathVariable Long id) {
        productService.delete(id);
        return "redirect:/";
    }

    @GetMapping("/direct")
    public void directLink (@RequestParam String param, HttpServletResponse response) throws IOException {
        Product prod = productService.getProductByName(param);
        if (prod == null) {
            prod = new Product();
        }
        response.setContentType("text/html");
        var writer = response.getWriter();
        String head = "<html>\n" +
                "  <head lang=\"en\">\n" +
                "    <title>CoffeeShop</title>\n" +
                "     \n" +
                "    <meta http-equiv=\"Content-Type\" content=\"text/html; charset=UTF-8\" />\n" +
                "    <link href=\"/webjars/bootstrap/3.3.4/css/bootstrap.min.css\" rel=\"stylesheet\" media=\"screen\" />\n" +
                "    <link href=\"/css/style.css\" rel=\"stylesheet\" media=\"screen\" />\n" +
                "    <script src=\"/webjars/jquery/2.1.4/jquery.js\"></script>\n" +
                "    <script src=\"/webjars/bootstrap/3.3.4/js/bootstrap.js\"></script>\n" +
                "   \n" +
                "  </head>\n" +
                "  <body><div class=\"container\"><div class=\"panel panel-default\">";

        String foot = "  </div></div></body>\n" +
                "</html>";


        writer.write(head);
        writer.write("<div class=\"panel-heading\"><h1>"+ param + "</h1></div>");

        String output = "<div class=\"panel-body\">" +
                "<ul>" +
                "<li>%s</li>" +
                "<li>%s</li>" +
                "<li>%s</li>" +
                "</ul>" +
                "</div>";

        writer.write(String.format(output, prod.getDescription(), prod.getProductType(), prod.getPrice()));
        writer.write(foot);

        response.getWriter().flush();
    }
}

@Controller
@RequestMapping("/profile")
public class ProfileController {
    private final PersonService personService;

    public ProfileController(PersonService personService) {
        this.personService = personService;
    }

    @GetMapping
    public String showProfile(Model model, Principal principal) {
        Person person = personService.findByUsername(principal.getName());
        model.addAttribute("person", person);
        return "profile";
    }

    @PostMapping
    public String saveProfile(@Valid Person person, BindingResult result, RedirectAttributes redirectAttributes) {
        String password = person.getPassword();
        String passwordConfirm = person.getPasswordConfirm();

        if (!password.isEmpty() && !password.equals(passwordConfirm)) {
            result.rejectValue("passwordConfirm", null, "Password does not match");
        }

        if (result.hasErrors()) {
            return "profile";
        }

        boolean isAdd = person.getId() == null;

        personService.savePerson(person);

        if (isAdd) {
            redirectAttributes.addFlashAttribute("message", "Your profile has been created successfully.");
        } else {
            redirectAttributes.addFlashAttribute("message", "Your profile has been updated successfully.");
        }

        return "redirect:/profile";
    }
}

@Controller
@RequestMapping("/register")
public class RegisterController {
    private final PersonService personService;

    public RegisterController(PersonService personService) {
        this.personService = personService;
    }

    @GetMapping
    public String showRegisterForm(Model model) {
        model.addAttribute("person", new Person());
        return "register";
    }

    @PostMapping
    public String register(@Valid Person person, BindingResult result, Model model, HttpServletRequest request) {
        String password = person.getPassword();
        String passwordConfirm = person.getPasswordConfirm();

        if (password.isEmpty()) {
            result.rejectValue("password", null, "Password cannot be empty");
        }

        if (passwordConfirm.isEmpty()) {
            result.rejectValue("passwordConfirm", null, "Password confirm cannot be empty");
        }

        if (!password.equals(passwordConfirm)) {
            result.rejectValue("passwordConfirm", null, "Password does not match");
        }

        boolean hasError = result.hasErrors();

        if (!hasError) {
            try {
                personService.registerNewPerson(person);
            } catch (EmailTakenException e) {
                hasError = true;
                result.rejectValue("email", "", "Email is already taken");
            } catch (UsernameTakenException e) {
                hasError = true;
                result.rejectValue("username", "", "Username is already taken");
            }
        }

        if (hasError) {
            model.addAttribute("person", person);
            return "register";
        }

        return "redirect:/";
    }

}

@Controller
public class UploadController {

    private final PersonService personService;

    public static String UPLOAD_DIRECTORY = System.getProperty("user.dir") + "/uploads";

    public UploadController(PersonService personService) {
        this.personService = personService;
    }

    @GetMapping("/uploadimage") public String displayUploadForm() {
        return "person/upload";
    }

    @PostMapping("/uploadimage") public String uploadImage(Model model, @RequestParam("image") MultipartFile file, Principal principal) throws IOException {
        var name = file.getOriginalFilename().replace(" ", "_");
        var fileNameAndPath = Paths.get(UPLOAD_DIRECTORY, name);
        Files.write(fileNameAndPath, file.getBytes());
        model.addAttribute("msg", "Uploaded images: " + name);

        if (principal == null) {
            model.addAttribute("message", "ERROR");
            return "person/upload";
        }

        var user = principal.getName();
        var person = personService.findByUsername(user);

        person.setProfilePic(name);
        personService.savePerson(person);
        return "person/upload";
    }
}

@Entity
@Table(name = "Orders")
public class Order {
    @Id
    @GeneratedValue
    private Long id;

    @Temporal(TemporalType.DATE)
    @DateTimeFormat(pattern = "dd/MM/yyyy")
    @NotNull(message = "Order date cannot be empty")
    private Date orderDate;

    @OneToMany(mappedBy = "order", fetch = FetchType.EAGER, cascade = CascadeType.ALL)
    private List<OrderLine> orderLines = new ArrayList<>();

    @OneToOne
    private Person person;

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public List<OrderLine> getOrderLines() {
        return orderLines;
    }

    public Person getPerson() {
        return person;
    }

    public void setPerson(Person person) {
        this.person = person;
    }

    public Date getOrderDate() {
        return orderDate;
    }

    public void setOrderDate(Date orderDate) {
        this.orderDate = orderDate;
    }

    public int getQuantity() {
        int quantity = 0;
        for (OrderLine ol : this.orderLines) {
            quantity += ol.getQuantity();
        }
        return quantity;
    }

    public double getTotalAmount() {
        double totalAmount = 0;

        for (OrderLine ol : this.orderLines) {
            totalAmount += ol.getSubtotal();
        }
        return totalAmount;
    }

    public void addOrderLine(OrderLine orderLine) {
        orderLine.setOrder(this);
        this.orderLines.add(orderLine);
    }

    public void removeOrderLine(OrderLine orderLine) {
        this.orderLines.remove(orderLine);
        orderLine.setOrder(null);
    }

    public void clearOrderLines() {
        for (OrderLine orderLine : orderLines) {
            orderLine.setOrder(null);
        }
        orderLines.clear();
    }

    @Override
    public String toString() {
        return "Order{" +
                "id=" + id +
                ", orderDate=" + orderDate +
                ", orderLines=" + orderLines +
                ", person=" + person +
                '}';
    }
}

@Entity
public class OrderLine {
    @Id
    @GeneratedValue
    private Long id;

    @Min(value = 1)
    private int quantity;

    @Transient
    private Product product;

    @Column(length = 10000)
    private String productName;

    @NotNull(message = "Product price cannot be empty")
    @Min(value = 0, message = "Product price must be greater than or equal to 0")
    private Double price;

    @ManyToOne
    private Order order;

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public int getQuantity() {
        return quantity;
    }

    public void setQuantity(int quantity) {
        this.quantity = quantity;
    }

    public Product getProduct() {
        return product;
    }

    public void setProduct(Product product) {
        this.product = product;
    }

    public String getProductName() {
        return productName;
    }

    public void setProductName(String productName) {
        this.productName = productName;
    }

    public void setPrice(Double price) {
        this.price = price;
    }

    public Order getOrder() {
        return order;
    }

    public void setOrder(Order order) {
        this.order = order;
    }

    public double getSubtotal() {
        return quantity * price;
    }

    public double getPrice() {
        return price;
    }

    @Override
    public String toString() {
        return "OrderLine{" +
                "id=" + id +
                ", quantity=" + quantity +
                ", product='" + product + '\'' +
                ", price=" + price +
                ", order=" + order +
                '}';
    }
}

