unit.class:
public class EmailTakenException extends Exception {
    public EmailTakenException(String message) {
        super(message);
    }

    public EmailTakenException(String message, Throwable cause) {
        super(message, cause);
    }
}

@ResponseStatus(value = HttpStatus.BAD_REQUEST)
