public class ExportOrder {


    private Long id;

    private Date orderDate;

    private List<ExportOrderLine> orderLines = new ArrayList<>();

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public Date getOrderDate() {
        return orderDate;
    }

    public void setOrderDate(Date orderDate) {
        this.orderDate = orderDate;
    }

    public List<ExportOrderLine> getOrderLines() {
        return orderLines;
    }

    public void setOrderLines(List<ExportOrderLine> orderLines) {
        this.orderLines = orderLines;
    }

    @Override
    public String toString() {
        return "ExportOrder{" +
                "id=" + id +
                ", orderDate=" + orderDate +
                ", orderLines=" + orderLines +
                '}';
    }

    public static ExportOrder fromOrder(Order order) {
        var exportOrder = new ExportOrder();
        exportOrder.setId(order.getId());
        exportOrder.setOrderDate(order.getOrderDate());
        var exportOrderLines = order.getOrderLines().stream()
                .map(ExportOrderLine::fromOrderLine)
                .collect(Collectors.toList());
        exportOrder.setOrderLines(exportOrderLines);
        return exportOrder;
    }
}

public class ExportOrderConvertor {

    public static Order createOrders(ExportOrder eo, Person person) {
        var order = new Order();
        order.setOrderDate(eo.getOrderDate());
        order.setPerson(person);
        eo.getOrderLines().forEach(eol -> order.addOrderLine(createOrderLines(eol)));
        return order;
    }

    private static OrderLine createOrderLines(ExportOrderLine eol) {
        var line = new OrderLine();
        line.setPrice(eol.getPrice());
        line.setProductName(eol.getProductName());
        line.setQuantity(eol.getQuantity());
        return line;
    }
}

