public class XML2OrderParser {

    private SAXParserFactory factory = SAXParserFactory.newInstance();

    public List<ExportOrder> parse(InputStream f) throws ParserConfigurationException, SAXException, IOException {
        SAXParser saxParser = factory.newSAXParser();
        OrderHandler handler = new OrderHandler();
        saxParser.getXMLReader().setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        saxParser.getXMLReader().setFeature("http://xml.org/sax/features/external-general-entities", false);


        saxParser.parse(f, handler);
        return handler.orders;
    }

    class OrderHandler extends DefaultHandler {
        boolean order, od, oline, olquant, olpname, olprice = false;
        String orderDate = "", lineQuantity = "", lineProductName = "", linePrice = "";

        public List<ExportOrder> orders = new ArrayList<>();
        List<ExportOrderLine> orderLines = new ArrayList();

        public void startElement(String uri, String localName, String qName, Attributes attributes) throws SAXException {
            if (qName.equalsIgnoreCase("Order")) order = true;
            if (qName.equalsIgnoreCase("orderDate")) od = true;

            if (qName.equalsIgnoreCase("OrderLine")) oline = true;
            if (qName.equalsIgnoreCase("quantity")) olquant = true;
            if (qName.equalsIgnoreCase("productName")) olpname = true;
            if (qName.equalsIgnoreCase("price")) olprice = true;
        }

        public void characters(char ch[], int start, int length) throws SAXException {

            if (od && order) {
                orderDate += new String(ch, start, length);
            }

            if (olquant && oline && order) {
                lineQuantity += new String(ch, start, length);
            }

            if (olpname && oline && order) {
                lineProductName += new String(ch, start, length);
            }

            if (olprice && oline && order) {
                linePrice += new String(ch, start, length);
            }

        }

        public void endElement(String uri, String localName, String qName) throws SAXException {
            if (qName.equalsIgnoreCase("Order")) order = false;
            if (qName.equalsIgnoreCase("orderDate")) od = false;

            if (qName.equalsIgnoreCase("OrderLine")) oline = false;
            if (qName.equalsIgnoreCase("quantity")) olquant = false;
            if (qName.equalsIgnoreCase("productName")) olpname = false;
            if (qName.equalsIgnoreCase("price")) olprice = false;


            if (qName.equalsIgnoreCase("OrderLine")) {
                ExportOrderLine ol = new ExportOrderLine();
                ol.setPrice(Double.valueOf(linePrice));
                ol.setProductName(lineProductName);
                ol.setQuantity(Integer.parseInt(lineQuantity));
                orderLines.add(ol);
                resetOline();
            }

            if (qName.equalsIgnoreCase("Order")) {
                ExportOrder order = new ExportOrder();
                order.setOrderDate(Date.valueOf(orderDate));
                order.setOrderLines(orderLines);
                orders.add(order);
                resetOrder();
            }

        }

        private void resetOline() {
            oline = false;
            olquant = false;
            olpname = false;
            olprice = false;

            lineQuantity = "";
            lineProductName = "";
            linePrice = "";
        }

        private void resetOrder() {
            order = false;
            od = false;
            orderDate = "";

            resetOline();
            orderLines = new ArrayList<>();
        }

    }
}

public class XMLExporter {

    public static String exportOrders(List<Order> orders) throws XMLStreamException, TransformerException {
        var stringOut = new StringWriter();
        var factory = XMLOutputFactory.newInstance();
        var writer = factory.createXMLStreamWriter(stringOut);

        writer.writeStartDocument("utf-8", "1.0");

        writer.writeStartElement("Orders");

        for (var order : orders) {
            writer.writeStartElement("Order");

            writeElement(writer, "id", order.getId().toString());
            writeElement(writer, "orderDate", order.getOrderDate().toString());

            for (var ol : order.getOrderLines()) {
                writer.writeStartElement("OrderLine");
                writeElement(writer, "id", ol.getId().toString());
                writeElement(writer, "quantity", String.valueOf(ol.getQuantity()));
                writeElement(writer, "productName", ol.getProductName());
                writeElement(writer, "price", String.valueOf(ol.getPrice()));
                writer.writeEndElement();
            }
            writer.writeEndElement();
        }
        writer.writeEndElement();
        writer.flush();
        writer.close();
        return formatXML(stringOut.toString());
    }

    private static void writeElement(XMLStreamWriter writer, String elementName, String value) throws XMLStreamException {
        writer.writeStartElement(elementName);
        writer.writeCharacters(value);
        writer.writeEndElement();
    }

    private static String formatXML(String xml) throws TransformerException {
        var transformerFactory = TransformerFactory.newInstance();
        var transformer = transformerFactory.newTransformer();

        transformer.setOutputProperty(OutputKeys.INDENT, "yes");
        transformer.setOutputProperty(OutputKeys.STANDALONE, "yes");

        var source = new StreamSource(new StringReader(xml));
        var output = new StringWriter();
        transformer.transform(source, new StreamResult(output));

        return output.toString();
    }

}

public class XMLParser {

    XMLInputFactory xmlInputFactory = XMLInputFactory.newInstance();

    XMLEventReader reader;
    List<ExportOrder> orders = new ArrayList<>();
    ExportOrder order = null;
    ExportOrderLine orderLine = null;

    public static XMLParser getNewInstance() {
        return new XMLParser();
    }



    public List<ExportOrder> parse(InputStream inputStream) throws XMLStreamException, XMLParseException {
        reader = xmlInputFactory.createXMLEventReader(inputStream);

        while (reader.hasNext()) {
            var nextEvent = reader.nextEvent();
            handleEvent(nextEvent);
        }

        return orders;
    }

    private void handleEvent(XMLEvent nextEvent) throws XMLParseException, XMLStreamException {
        if (nextEvent.isStartElement()) {
            StartElement startElement = nextEvent.asStartElement();
            switch (startElement.getName().getLocalPart()) {

                case "Order":
                    order = new ExportOrder();
                    break;

                case "orderDate":
                    nextEvent = reader.nextEvent();
                    if (order == null) throw new XMLParseException("Invalid XML");
                    order.setOrderDate(Date.valueOf(nextEvent.asCharacters().getData()));
                    break;

                case "OrderLine":
                    if (order == null) throw new XMLParseException("Invalid XML");
                    orderLine = new ExportOrderLine();
                    break;

                case "quantity":
                    nextEvent = reader.nextEvent();
                    if (orderLine == null) throw new XMLParseException("Invalid XML");
                    orderLine.setQuantity(Integer.parseInt(nextEvent.asCharacters().getData()));
                    break;

                case "productName":
                    nextEvent = reader.nextEvent();
                    if (orderLine == null) throw new XMLParseException("Invalid XML");
                    String productName = "";
                    while (nextEvent.isCharacters()) {
                       productName += nextEvent.asCharacters().getData();
                       nextEvent = reader.nextEvent();
                    }
                    orderLine.setProductName(productName);
                    handleEvent(nextEvent);
                    break;

                case "price":
                    nextEvent = reader.nextEvent();
                    if (orderLine == null) throw new XMLParseException("Invalid XML");
                    orderLine.setPrice(Double.valueOf(nextEvent.asCharacters().getData()));
                    break;

            }
        }

        if (nextEvent.isEndElement()) {
            EndElement endElement = nextEvent.asEndElement();
            switch (endElement.getName().getLocalPart()){
                case "Order":
                    orders.add(order);
                    break;

                case "OrderLine":
                    order.getOrderLines().add(orderLine);
                    break;

            }
        }
    }



}

public class YamlImportExport {


    public static final MediaType MEDIA_TYPE_YAML = MediaType.valueOf("text/yaml");

    public static String exportOrders(List<Order> orders) {
        var exportOrders = orders.stream()
                .map(ExportOrder::fromOrder)
                .collect(Collectors.toList());

        DumperOptions options = new DumperOptions();
        options.setIndent(2);
        options.setPrettyFlow(true);
        options.setDefaultFlowStyle(DumperOptions.FlowStyle.BLOCK);
        Yaml yaml = new Yaml(options);
        return yaml.dump(exportOrders);
    }


    public static List<Order> importOrders(InputStream inputStream, Person person) {
        Yaml yaml = new Yaml();
        List<ExportOrder> orders = yaml.load(inputStream);
        return orders.stream()
                .map(eo -> ExportOrderConvertor.createOrders(eo, person))
                .collect(Collectors.toList());
    }

}

